def has_gap_pair(times, k):
    lo, hi = 0, len(times) - 1
    while lo < hi:
        diff = times[hi] - times[lo]
        if diff == k:
            return True
        if diff < k:
            lo += 1
        else:
            hi -= 1
    return False
```

