```python
def is_valid_set_score(s):
    if not isinstance(s, str) or not s:
        return False
    parts = s.split('-')
    if len(parts) != 2:
        return False
    try:
        a, b = int(parts[0]), int(parts[1])
    except ValueError:
        return False
    if a < 0 or b < 0 or a > 7 or b > 7:
        return False
    if a == b:
        return False
    if a > b:
        return a >= 6
    return b >= 6
```

```python
def longest_repeat_run(statuses):
    best = 0
    cur = 0
    prev = None
    for s in statuses:
        if s == prev:
            cur += 1
        else:
            cur = 1
            prev = s
        if cur > best:
            best = cur
    return best
```

